import attr
import logging
from typing import Optional
from .connection_details import SshServiceDetails, HttpConnectionDetails

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@attr.s(cmp=False)
class NADCM(object):
    """
    This class defines an instance of NADCM.

    :param Optional[SshServiceDetails] ssh_details: SSH details for NADCM node
    :param Optional[HttpConnectionDetails] api_connection_details: HTTP details for NADCM Main URL
    """
    ssh_details = attr.ib(default=None, type=Optional[SshServiceDetails])
    api_connection_details = attr.ib(default=None, type=Optional[HttpConnectionDetails])

    def __taf_contract_ssh__(self):
        return self.ssh_details.__taf_contract_ssh__()
